mapper.select:
SELECT * FROM pull_task_group_marketing_group_occupancy WHERE released_at IS NULL AND group_jid IN
#{groupJid}
ORDER BY id ASC

mapper.update:
UPDATE pull_task_group_marketing_group_occupancy
SET expires_at = #{expiresAt}, updated_at = #{now}
WHERE released_at IS NULL
  AND occupancy_type = 'WAITING'
  AND reservation_token = #{reservationToken}
  AND created_by = #{createdBy}
  AND expires_at > #{now}

UPDATE pull_task_group_marketing_group_occupancy
SET task_name_snapshot = #{taskName},
    planned_start_at = #{plannedStartAt},
    updated_at = #{now}
WHERE released_at IS NULL
  AND occupancy_type = 'WAITING'
  AND reservation_token = #{reservationToken}
  AND created_by = #{createdBy}

UPDATE pull_task_group_marketing_group_occupancy
SET released_at = #{now}, updated_at = #{now}
WHERE released_at IS NULL
  AND occupancy_type = 'WAITING'
  AND expires_at IS NOT NULL
  AND expires_at <= #{now}

UPDATE pull_task_group_marketing_group_occupancy
SET released_at = #{releasedAt}, updated_at = #{releasedAt}
WHERE released_at IS NULL
  AND occupancy_type = 'WAITING'
  AND reservation_token = #{reservationToken}
  AND group_jid = #{groupJid}
  AND created_by = #{createdBy}

UPDATE pull_task_group_marketing_group_occupancy
SET released_at = #{releasedAt}, updated_at = #{releasedAt}
WHERE released_at IS NULL
  AND occupancy_type = 'WAITING'
  AND reservation_token = #{reservationToken}
  AND created_by = #{createdBy}
